#![no_std]
//! COM interfaces from CommonLib `REX/W32` (IUnknown, DXGI, D3D11).
//!
//! Kept in its own crate so renderers can be built and tested without
//! libskyrim; libskyrim re-exports everything as `libskyrim::rex::*`.
//!
//! `unknown.rs`, `dxgi.rs` and `d3d11.rs` are generated by
//! `scripts/generate_rex_com.py`: every interface is `{ vtbl: *const Vtbl }` and
//! every vtable slot is a raw pointer named after the C++ method, nested
//! through `base` in inheritance order. Call a slot with [`com_call!`], which
//! transmutes it to the given `extern "system"` signature.
//!
//! Plain data types (descs, enums, `HRESULT`) live in `types.rs` because
//! `windows-sys` does not ship the Direct3D/DXGI namespaces.

mod d3d11;
mod dxgi;
mod types;
mod unknown;

pub use d3d11::*;
pub use dxgi::*;
pub use types::*;
pub use unknown::*;

/// Windows `GUID` / `IID`.
#[repr(C)]
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct GUID {
    pub data1: u32,
    pub data2: u16,
    pub data3: u16,
    pub data4: [u8; 8],
}

/// Calls a COM vtable slot.
///
/// ```ignore
/// let hr = com_call!(device, CreateBuffer: fn(*const D3D11_BUFFER_DESC, *const D3D11_SUBRESOURCE_DATA, *mut *mut ID3D11Buffer) -> HRESULT; &desc, null(), &mut buf);
/// let refs = com_call!(device, base.Release: fn() -> u32;);
/// ```
///
/// `this` must be a non-null pointer to a live COM object of the named
/// interface; the signature must match the C++ declaration (excluding `this`).
#[macro_export]
macro_rules! com_call {
    ($this:expr, $($slot:ident).+ : fn($($arg:ty),* $(,)?) $(-> $ret:ty)?; $($a:expr),* $(,)?) => {{
        let this = $this;
        #[allow(unused_unsafe)]
        unsafe {
            let f: unsafe extern "system" fn(*mut core::ffi::c_void $(, $arg)*) $(-> $ret)? =
                core::mem::transmute((*(*this).vtbl).$($slot).+);
            f(this.cast::<core::ffi::c_void>() $(, $a)*)
        }
    }};
}

/// `IUnknown::Release` on any interface pointer (null is ignored).
///
/// # Safety
/// `ptr` must be null or a live COM object.
#[inline]
pub unsafe fn com_release<T>(ptr: *mut T) -> u32 {
    if ptr.is_null() {
        return 0;
    }
    let unknown = ptr.cast::<IUnknown>();
    com_call!(unknown, Release: fn() -> u32;)
}

/// `IUnknown::AddRef` on any interface pointer (null is ignored).
///
/// # Safety
/// `ptr` must be null or a live COM object.
#[inline]
pub unsafe fn com_add_ref<T>(ptr: *mut T) -> u32 {
    if ptr.is_null() {
        return 0;
    }
    let unknown = ptr.cast::<IUnknown>();
    com_call!(unknown, AddRef: fn() -> u32;)
}
